		readonly itemsScanned: number;
	};
}

export type WorkflowsTrainingSummaryOperations =
	| {
			readonly workouts: WorkoutsListOperation;
			readonly bodyMeasurements: BodyMeasurementsListOperation;
	  }
	| {
			readonly workouts: {
