export function paginationFields({
	defaultPageSize,
	maxPageSize,
	integerPage = true,
}: PaginationSchemaOptions) {
	const pageNumber = z.coerce.number().gte(1);
	return {
		page: integerPage ? pageNumber.int() : pageNumber,
		page_size: z.coerce
			.number()
			.int()
