type OperationSafety =
	| "read"
	| "non-idempotent-write"
	| "idempotent-write";

function operation<T>(
	id: string,
	safety: OperationSafety,
	value: T,
): {
	readonly descriptor: { readonly id: string; readonly safety: OperationSafety };
	readonly effect: ReturnType<typeof vi.fn>;
	readonly execute: ReturnType<typeof vi.fn>;
} {
	const effect = vi.fn((_input?: unknown, _options?: unknown) =>
		Effect.succeed(value),
	);
	return {
		descriptor: { id, safety },
		effect,
		execute: vi.fn(),
	};
}

